method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0
    ensures |result| == |numbers|
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(0, i, numbers)
{
    var maxVal := numbers[0];
    var res := new int[|numbers|];

    var i := 0;
    while i < |numbers|
        invariant 0 <= i <= |numbers|
        invariant forall j :: 0 <= j < i ==> res[j] == Max(0, j, numbers)
    {
        if numbers[i] > maxVal {
            maxVal := numbers[i];
        }
        res[i] := maxVal;
        i := i + 1;
    }
    result := res;
}

function Max(start: int, end: int, seq: seq<int>): int
    requires 0 <= start <= end < |seq|
    ensures result == Max(seq[start..end]) // The maximum value in the subsequence
{
    var maxValue := seq[start];
    var i := start + 1;
    while i <= end
        invariant start <= i <= end + 1
        invariant maxValue == Max(seq[start..i-1])
    {
        if seq[i] > maxValue {
            maxValue := seq[i];
        }
        i := i + 1;
    }
    return maxValue;
}
